// site/hero/memory/memory.js — jeu de Memory fictif, entièrement jouable.
// Signature : des cartes qui se retournent vraiment (3D, coupé en mouvement réduit), un jeu
// d'icônes Lucide par difficulté ; les paires
// trouvées restent face visible, teintées ; la partie se joue au clavier (flèches dans la grille).
// Composants : Progress (paires), Alert (partie gagnée, « Rejouer »), DropdownMenu (nouvelle
// partie : la taille de grille se choisit là ; chaque entrée est une action, MenuItem), Button. Chaque carte est un
// bouton dont le nom dit son état.
// Parcours : une partie Facile est lancée d'office ; changer de taille, c'est commencer une
// nouvelle partie — le choix vit donc dans « Nouvelle partie », pas au-dessus de la grille.

import { signal, focus } from 'reefjs';
import { DropdownMenu } from 'nodus/components/dropdown-menu/dropdown-menu.js';
import { MenuLabel, MenuItem } from 'nodus/components/menu/menu.js';
import { registry } from 'nodus/core/component-registry.js';
import { Progress } from 'nodus/components/progress/progress.js';
import { Alert } from 'nodus/components/alert/alert.js';
import { Button } from 'nodus/components/button/button.js';
import { Icon } from 'nodus/core/icons.js';
import { hid, L, tx } from '../kit/ui.js';

const ID = 'memory';
const id = part => hid(ID, part);

// Grilles : lignes × colonnes (au plus quatre lignes : la carte garde sa hauteur).
export const GRIDS = {
  s: { rows: 3, cols: 4, fr: 'Facile', en: 'Easy' },
  m: { rows: 4, cols: 4, fr: 'Moyen', en: 'Medium' },
  l: { rows: 4, cols: 5, fr: 'Difficile', en: 'Hard' },
};
// Un jeu d'icônes Lucide par difficulté : six fruits, huit animaux, dix motifs du ciel. Chaque
// motif a son nom (annoncé quand la carte est visible) et une teinte (repère visuel, pas le seul).
const face = (icon, fr, en) => ({ icon, name: { fr, en } });
export const FACES = {
  s: [face('apple', 'pomme', 'apple'), face('cherry', 'cerises', 'cherries'), face('grape', 'raisin', 'grapes'),
    face('banana', 'banane', 'banana'), face('carrot', 'carotte', 'carrot'), face('citrus', 'agrume', 'citrus')],
  m: [face('cat', 'chat', 'cat'), face('dog', 'chien', 'dog'), face('bird', 'oiseau', 'bird'), face('fish', 'poisson', 'fish'),
    face('rabbit', 'lapin', 'rabbit'), face('turtle', 'tortue', 'turtle'), face('squirrel', 'écureuil', 'squirrel'), face('snail', 'escargot', 'snail')],
  l: [face('sun', 'soleil', 'sun'), face('moon', 'lune', 'moon'), face('star', 'étoile', 'star'), face('cloud', 'nuage', 'cloud'),
    face('cloud-rain', 'pluie', 'rain'), face('snowflake', 'flocon', 'snowflake'), face('zap', 'éclair', 'lightning'),
    face('rainbow', 'arc-en-ciel', 'rainbow'), face('umbrella', 'parapluie', 'umbrella'), face('wind', 'vent', 'wind')],
};
const TONES = 8; // teintes des motifs (data-tone, site/styles.css)
export const MISMATCH_MS = 900;

/** Mélange déterministe (graine) : même graine, même donne — les tests et le rendu restent purs. */
export function deal(pairs, seed) {
  const deck = Array.from({ length: pairs * 2 }, (_, i) => i % pairs);
  let x = seed * 2654435761 >>> 0 || 1;
  for (let i = deck.length - 1; i > 0; i--) {
    x ^= x << 13; x ^= x >>> 17; x ^= x << 5; x >>>= 0;
    const j = x % (i + 1);
    [deck[i], deck[j]] = [deck[j], deck[i]];
  }
  return deck;
}

/** Nouvelle partie. */
export const newGame = (grid, seed) => ({ grid, seed, deck: deal(GRIDS[grid].rows * GRIDS[grid].cols / 2, seed), open: [], found: [], moves: 0, cursor: 0 });

/**
 * Retourner la carte `i`. Deux cartes ouvertes : un coup de plus ; une paire reste trouvée, sinon
 * les deux cartes restent visibles jusqu'à `hide()`. Rien ne se passe sur une carte déjà visible
 * ni tant qu'une paire ratée est affichée.
 */
export function flip(game, i) {
  if (game.open.length === 2 || game.open.includes(i) || game.found.includes(game.deck[i])) return game;
  const open = [...game.open, i];
  if (open.length < 2) return { ...game, open };
  const [a, b] = open;
  const moves = game.moves + 1;
  return game.deck[a] === game.deck[b]
    ? { ...game, moves, open: [], found: [...game.found, game.deck[a]] }
    : { ...game, moves, open };
}

/** Paire ratée : les deux cartes se referment. */
export const hide = game => ({ ...game, open: [] });

export const won = game => game.found.length * 2 === game.deck.length;

const state = signal({ ...newGame('s', 1), best: {} }, `hero-${ID}`);
let timer = null;

/** Taille de la grille : dans la ligne d'avancement, au-dessus de la grille qu'elle redessine. */
/**
 * « Nouvelle partie » : un menu dont chaque entrée LANCE une partie de cette taille — une action,
 * donc MenuItem (qui referme le menu et rend le focus), pas MenuRadioItem (qui reste ouvert, pour
 * cocher plusieurs choix d'affilée). La taille en cours est cochée, et dite « en cours ».
 * DropdownMenu porte reef-ignore : re-rendu par registry.remount à chaque changement de partie.
 */
function newGameMenu() {
  return DropdownMenu({ id: id('new'), side: 'top', align: 'end',
    trigger: Button({ label: tx('Nouvelle partie', 'New game'), size: 'sm', variant: won(state) ? 'default' : 'outline',
      iconStart: Icon('rotate-ccw', { size: 14 }), iconEnd: Icon('chevron-down', { size: 14 }) }),
    children: MenuLabel({ label: tx('Taille de la grille', 'Grid size') }) + Object.entries(GRIDS).map(([value, g]) => {
      const current = state.grid === value;
      return MenuItem({ label: `${L(g)}${current ? `<span class="sr-only"> ${tx('(en cours)', '(current)')}</span>` : ''}`, shortcut: `${g.rows}×${g.cols}`,
        icon: current ? Icon('check', { size: 14 }) : '<span class="hero-menu-spacer"></span>', attrs: { 'data-value': value } });
    }).join('') });
}
// Après la fermeture du menu (MenuItem le referme juste après `dropdown-menu:select`) : remonté
// pendant qu'il est ouvert, l'ancien behavior détruit laisserait son panneau portalé dans <body>.
const refreshMenu = () => setTimeout(() => registry.remount(id('new'), newGameMenu()));

function card(f, i) {
  const { icon, name } = FACES[state.grid][f];
  const found = state.found.includes(f);
  const shown = found || state.open.includes(i);
  const what = found ? tx(`${L(name)}, paire trouvée`, `${L(name)}, pair found`) : shown ? L(name) : tx('cachée', 'hidden');
  return `<li><button type="button" class="hero-memory-card${shown ? ' is-flipped' : ''}${found ? ' is-found' : ''}"
      id="${id(`card-${i}`)}" tabindex="${i === state.cursor ? 0 : -1}" data-action="hero:memory-flip" data-index="${i}" aria-label="${tx(`Carte ${i + 1} : ${what}`, `Card ${i + 1}: ${what}`)}"
      ${found ? 'aria-disabled="true"' : ''}>
    <span class="hero-memory-inner" aria-hidden="true">
      <span class="hero-memory-back"></span>
      <span class="hero-memory-face" data-tone="${f % TONES}">${Icon(icon, { size: 24 })}</span>
    </span>
  </button></li>`;
}

function body() {
  const g = GRIDS[state.grid];
  const pairs = state.deck.length / 2;
  const done = won(state);
  const last = state.open.length === 2 ? tx('Raté : les cartes se referment.', 'No match: the cards turn back.') : '';
  return `<div class="hero-memory-status">
      <span class="hero-label">${tx(`${state.found.length} paire${state.found.length > 1 ? 's' : ''} sur ${pairs}`, `${state.found.length} of ${pairs} pairs`)}</span>
      ${Progress({ value: Math.round((state.found.length / pairs) * 100), label: tx('Paires trouvées', 'Pairs found'), variant: done ? 'success' : 'default',
        attrs: { class: 'hero-progress-thin hero-memory-progress' } })}
      <span class="hero-meta">${L(g)} · ${g.rows}×${g.cols}</span>
    </div>
    ${done
      ? Alert({ variant: 'success', icon: Icon('sparkles', { size: 16 }), title: tx('Bravo !', 'Well done!'),
          description: tx(`Grille terminée en ${state.moves} coups${state.best[state.grid] === state.moves ? ' : meilleur score' : ''}.`,
            `Grid cleared in ${state.moves} moves${state.best[state.grid] === state.moves ? ': best score' : ''}.`),
          action: Button({ label: tx('Rejouer', 'Play again'), size: 'sm', attrs: { id: id('again'), 'data-action': 'hero:memory-restart' } }) })
      : ''}
    <ul class="hero-memory" style="--cols:${g.cols};--rows:${g.rows}" aria-label="${tx(`Grille de ${g.rows} sur ${g.cols}, flèches pour se déplacer`, `${g.rows} by ${g.cols} grid, arrow keys to move`)}"
      data-keydown="hero:memory-key"${done ? ' hidden' : ''}>
      ${state.deck.map(card).join('')}
    </ul>
    <p class="sr-only" role="status">${last}</p>`;
}

function foot() {
  const best = state.best[state.grid];
  return `<p class="hero-meta"><span class="hero-foot-figure">${state.moves}</span> ${tx(`coup${state.moves > 1 ? 's' : ''}`, `move${state.moves === 1 ? '' : 's'}`)}
      ${best ? ` · ${tx(`record ${best}`, `best ${best}`)}` : ''}</p>
    ${newGameMenu()}`;
}

function restart(grid = state.grid) {
  clearTimeout(timer);
  Object.assign(state, newGame(grid, state.seed + 1));
  refreshMenu();
}

function install({ on, onComponent }) {
  // Une entrée du menu = une nouvelle partie de cette taille ; le focus revient sur la grille.
  onComponent('dropdown-menu:select', id('new'), ({ value }) => {
    if (!GRIDS[value]) return;
    restart(value);
    focus(`#${id('card-0')}`);
  });
  on('hero:memory-flip', (e, el) => {
    const index = Number(el.dataset.index);
    state.cursor = index;
    const next = flip(state, index);
    if (next === state) return;
    Object.assign(state, next);
    if (state.open.length === 2) {
      timer = setTimeout(() => Object.assign(state, hide(state)), MISMATCH_MS);
    } else if (won(state)) {
      const best = state.best[state.grid];
      state.best = { ...state.best, [state.grid]: best ? Math.min(best, state.moves) : state.moves };
      // La grille disparaît : le focus passe sur « Rejouer », et « Nouvelle partie » est mis en avant.
      refreshMenu();
      focus(`#${id('again')}`);
    }
  });
  on('hero:memory-restart', () => { restart(); focus(`#${id('card-0')}`); });
  // Flèches : déplacement dans la grille — tabindex itinérant, une tabulation pour entrer, une pour sortir.
  on('hero:memory-key', (e) => {
    const from = e.target.closest?.('[data-index]');
    const { cols } = GRIDS[state.grid];
    const step = { ArrowRight: 1, ArrowLeft: -1, ArrowDown: cols, ArrowUp: -cols }[e.key];
    if (!from || !step) return;
    const to = Number(from.dataset.index) + step;
    if (to < 0 || to >= state.deck.length) return;
    e.preventDefault();
    state.cursor = to;
    focus(`#${id(`card-${to}`)}`);
  }, 'keydown');
}

export default {
  id: ID,
  title: { fr: 'Memory', en: 'Memory' },
  summary: { fr: 'Un Memory jouable : trois tailles de grille, coups, paires.', en: 'A playable Memory game: three grid sizes, moves, pairs.' },
  icon: 'grid-3x3', accent: 'amber',
  state, body, foot, install,
  stop: () => clearTimeout(timer),
};

