/* site/hero/memory/memory.css — styles propres à la carte « Memory ». Le gabarit commun (en-tête,
   corps, pied, niveaux de texte, compteur) est dans ../kit/card.css. */

.hero-memory-status { display: flex; align-items: center; gap: var(--space-3); }
.hero-memory-status .toggle-group { flex: none; }
.hero-memory-status .hero-label { white-space: nowrap; }
.hero-memory-progress { flex: 1; }
.hero-memory {
  flex: 1 1 0; min-height: 0; list-style: none; margin: 0; padding: 0;
  display: grid; grid-template-columns: repeat(var(--cols, 4), minmax(0, 1fr)); grid-template-rows: repeat(var(--rows, 3), minmax(0, 1fr)); gap: var(--space-1-5);
}
.hero-memory > li { display: flex; min-height: 0; }
.hero-memory-card { flex: 1; padding: 0; border: 0; background: none; border-radius: var(--radius-md); perspective: 40rem; cursor: pointer; min-height: var(--space-10); }
.hero-memory-card:focus-visible { outline: 2px solid var(--color-ring); outline-offset: 2px; }
.hero-memory-card[aria-disabled="true"] { cursor: default; }
.hero-memory-inner { position: relative; display: block; width: 100%; height: 100%; transform-style: preserve-3d; transition: transform var(--duration-slow) var(--ease-out); }
.hero-memory-card.is-flipped .hero-memory-inner { transform: rotateY(180deg); }
.hero-memory-back, .hero-memory-face {
  position: absolute; inset: 0; display: grid; place-items: center; border-radius: var(--radius-md); backface-visibility: hidden;
  border: 1px solid var(--color-border);
}
.hero-memory-back {
  background: linear-gradient(135deg, var(--hero-accent-muted, var(--color-primary-muted)), var(--color-bg-muted));
  background-image: radial-gradient(circle at 50% 50%, var(--hero-accent, var(--color-primary)) 0 var(--space-1), transparent calc(var(--space-1) + 1px)),
    linear-gradient(135deg, var(--hero-accent-muted, var(--color-primary-muted)), var(--color-bg-muted));
}
.hero-memory-card:hover:not([aria-disabled="true"]) .hero-memory-back { border-color: var(--hero-accent, var(--color-primary)); }
.hero-memory-face { transform: rotateY(180deg); background: var(--color-bg-elevated); color: var(--_tone, var(--color-fg)); }
.hero-memory-face[data-tone="0"] { --_tone: var(--hero-rose); }
.hero-memory-face[data-tone="1"] { --_tone: var(--color-info); }
.hero-memory-face[data-tone="2"] { --_tone: var(--color-success); }
.hero-memory-face[data-tone="3"] { --_tone: var(--hero-amber); }
.hero-memory-face[data-tone="4"] { --_tone: var(--color-primary); }
.hero-memory-face[data-tone="5"] { --_tone: var(--hero-teal); }
.hero-memory-face[data-tone="6"] { --_tone: var(--color-destructive); }
.hero-memory-face[data-tone="7"] { --_tone: var(--color-warning); }
.hero-memory-card.is-found .hero-memory-face { background: var(--hero-accent-muted, var(--color-primary-muted)); border-color: var(--hero-accent, var(--color-primary)); }

/* Mouvement réduit : la carte reste immobile. */
@media (prefers-reduced-motion: reduce) {
  .hero-memory-inner { transition: none; }
}
.hero-menu-spacer { display: inline-block; width: 14px; } /* aligne les entrées sans coche */

site/hero/kit/app.js:
// site/hero/kit/app.js — démarrage d'une mini-app : une carte de la vitrine, seule dans sa page.
//
// Même architecture qu'une application générée par le starter, en plus court : behaviors Nodus,
// icônes, langue, délégation d'événements, puis un îlot Reef qui se re-rend sur le signal de la
// carte. Rien ne vient du site de documentation : la mini-app tourne telle quelle, ouverte seule
// ou dans l'iframe de sa page de code (#/showcase/<carte>).

import { component } from 'reefjs';
import 'nodus/reef/reef-init.js'; // enregistre tous les behaviors (Select, Tabs, Popover…)
import { registerIcons } from 'nodus/core/icons.js';
import { nodusIcons } from 'nodus/core/icons-lucide.js';
import { setStrings, stringsFr, DEFAULT_LOCALE } from 'nodus/core/i18n.js';
import { stringsEn } from 'nodus/core/i18n-en.js';
import { initTooltips } from 'nodus/components/tooltip/tooltip-delegate.js';
import { installEvents, on, onComponent } from './events.js';
import { icons } from './icons.js';
import { frame, cardView, islandId } from './card.js';
import { L, onTarget } from './ui.js';

const param = name => new URLSearchParams(location.search).get(name);
const saved = key => { try { return localStorage.getItem(key); } catch { return null; } };

/** Langue : `?lang=`, sinon celle choisie sur le site, sinon celle du navigateur (fr ou en), sinon DEFAULT_LOCALE. */
function startLanguage() {
  const pick = v => (v === 'fr' || v === 'en' ? v : null);
  const lang = pick(param('lang')) ?? pick(saved('nodus:locale'))
    ?? pick((navigator.language || '').slice(0, 2).toLowerCase()) ?? DEFAULT_LOCALE;
  document.documentElement.lang = lang;              // lu par tx() et L() (kit/ui.js)
  setStrings(lang === 'en' ? stringsEn : stringsFr); // libellés par défaut des composants Nodus
}

/** Thème : `?theme=light|dark`, sinon celui choisi sur le site, sinon celui du système. */
function startTheme() {
  const theme = [param('theme'), saved('nodus:theme')].find(t => t === 'light' || t === 'dark');
  if (theme) document.documentElement.dataset.theme = theme;
}

/**
 * Monte une carte dans `root` : la page devient l'application de cette seule carte.
 * @param {object} card — export par défaut d'un module de carte (contrat : kit/card.js)
 * @param {HTMLElement} [root]
 */
export function startDemo(card, root = document.getElementById('app')) {
  startLanguage();
  startTheme();
  registerIcons(nodusIcons);
  registerIcons(icons);
  installEvents();
  initTooltips(); // infobulles en mode attribut (data-tooltip)
  document.title = `${L(card.title)} — Nodus`;

  card.install({ on, onComponent, onTarget });
  root.innerHTML = frame(card);
  component(`#${islandId(card)}`, () => cardView(card), { signals: [`hero-${card.id}`] });
  card.start?.();
}

site/hero/kit/card.js:
// site/hero/kit/card.js — le gabarit commun d'une carte : en-tête, corps, pied. Partagé par le
// carrousel de l'accueil (site/hero/index.js) et par chaque mini-app (kit/app.js).
//
// Contrat d'une carte (site/hero/<carte>/<carte>.js, export par défaut) :
//   { id, title: { fr, en }, summary: { fr, en }, icon, accent, state, body, foot, install, start?, stop? }
//   summary   une phrase : ce qu'on fait dans la carte (page Démos, page de code, recherche ⌘K)
//   state     signal Reef NOMMÉ `hero-<id>` : la carte se re-rend sur lui seul
//   body/foot fonctions pures de l'état (HTML). L'en-tête n'appartient pas à la carte : il dit quelle
//             app c'est (icône, nom, « Exemple fictif »), jamais son état ni ses contrôles, qui vivent
//             dans le corps ou le pied, à côté de ce qu'ils commandent.
//   install({ on, onComponent, onTarget })  pose les gestionnaires (délégation), une fois
//   start/stop  minuteries éventuelles (lecture audio, données « en direct »)

import { Card } from 'nodus/components/card/card.js';
import { Icon } from 'nodus/core/icons.js';
import { L, tx } from './ui.js';

// Une teinte d'identité par app, réservée à l'icône, au halo et à un élément signature (card.css).
export const ACCENTS = ['rose', 'info', 'primary', 'warning', 'amber', 'teal', 'success'];

/** Id de l'îlot : l'élément que Reef re-rend sur le signal de la carte. */
export const islandId = card => `hero-island-${card.id}`;

/**
 * Contenu de la carte (template de l'îlot) : en-tête (icône d'app à la teinte de l'app, nom en h3,
 * mention « Exemple fictif », actions de la carte), corps, pied ancré en bas.
 * `position` (« 01/12 ») et `code` (lien vers la page de code) : ajoutés par le carrousel de
 * l'accueil ; absents dans une mini-app, qui est elle-même ce code.
 */
export function cardView(card, { position, code } = {}) {
  return `<header class="hero-card-head">
      <span class="hero-app-icon" aria-hidden="true">${Icon(card.icon, { size: 16 })}</span>
      <div class="hero-app-id">
        <h3 class="hero-app-name">${L(card.title)}</h3>
        <p class="hero-meta">${tx('Exemple fictif', 'Fictional sample')}${position ? ` · <span aria-hidden="true">${position}</span>` : ''}${code
          ? ` · <a class="hero-code-link" href="${code}" aria-label="${tx(`Code de la mini-app ${L(card.title)}`, `Code of the ${L(card.title)} mini-app`)}">${Icon('braces', { size: 12 })}${tx('Code', 'Code')}</a>` : ''}</p>
      </div>
    </header>
    <div class="hero-card-body">${card.body()}</div>
    <footer class="hero-card-foot">${card.foot()}</footer>`;
}

/** La carte complète : un Card Nodus à la teinte de l'app, qui contient l'îlot. */
export function frame(card, options) {
  return Card({ attrs: { class: `hero-card hero-card--${card.id}`, 'data-accent': card.accent }, children:
    `<div class="hero-island" id="${islandId(card)}">${cardView(card, options)}</div>` });
}

site/hero/kit/ui.js:
// site/hero/kit/ui.js — briques partagées des cartes de la vitrine : ids, langue, formats, compteur.
// Tout est pur : une carte = une fonction de son état et de la langue de la page.
// La langue est celle du document (`<html lang>`) : le site la pose à chaque changement de langue,
// une mini-app la pose au démarrage (kit/app.js). Aucune carte ne dépend donc du site.

import { Button } from 'nodus/components/button/button.js';
import { Icon } from 'nodus/core/icons.js';

/** Id d'un élément d'une carte : `hero-<carte>-<partie>` (uniques dans la page, SITE-6). */
export const hid = (card, part) => `hero-${card}-${part}`;

/** Langue de la page : 'fr' ou 'en'. */
export const lang = () => (document.documentElement.lang === 'en' ? 'en' : 'fr');

/** Texte dans la langue de la page. */
export const tx = (fr, en) => (lang() === 'en' ? en : fr);

/** Contenu bilingue `{ fr, en }` dans la langue de la page. */
export const L = value => (typeof value === 'string' ? value : value[lang()] ?? value.fr);

const intl = () => (lang() === 'en' ? 'en-GB' : 'fr-FR');
export const money = (n, digits = 2) => new Intl.NumberFormat(intl(), {
  style: 'currency', currency: 'EUR', minimumFractionDigits: digits, maximumFractionDigits: digits }).format(n);
export const num = n => new Intl.NumberFormat(intl()).format(n);
export const pct = n => new Intl.NumberFormat(intl(), { style: 'percent', maximumFractionDigits: 1 }).format(n);
export const date = (iso, opts = { day: 'numeric', month: 'short' }) =>
  new Intl.DateTimeFormat(intl(), opts).format(new Date(`${iso}T12:00:00`));

/** Nombre et nom accordé, dans la langue de la page : plural(2, ['adulte', 'adultes'], ['adult', 'adults']) → « 2 adultes ». */
export const plural = (n, [fr1, frN], [en1, enN]) => `${num(n)} ${lang() === 'en' ? (n === 1 ? en1 : enN) : (n <= 1 ? fr1 : frN)}`;

/** Heure d'un instant (horodatage en ms) : « 14:05 » ou « 2:05 PM ». */
export const time = ts => new Intl.DateTimeFormat(intl(), { hour: 'numeric', minute: '2-digit' }).format(new Date(ts));

/** m:ss */
export const clock = s => `${Math.floor(s / 60)}:${String(Math.floor(s % 60)).padStart(2, '0')}`;

/**
 * Compteur − valeur + (passagers, quantité) : un groupe nommé, une valeur annoncée, des bornes
 * signalées par aria-disabled — pas `disabled`, qui ferait perdre le focus au bouton atteint.
 * `size: 'sm'` : boutons de 32 px (Button `icon-sm`), à côté d'autres contrôles `sm`.
 */
export function counter({ id, label, value, text, min, max, action, hiddenLabel = false, size = 'md' }) {
  const step = (delta, icon, name, off) => Button({
    label: '', size: size === 'sm' ? 'icon-sm' : 'icon', variant: 'outline', iconStart: Icon(icon, { size: 14 }),
    attrs: { 'aria-label': name, 'aria-controls': `${id}-value`, 'aria-disabled': off ? 'true' : false,
      'data-action': action, 'data-delta': String(delta) },
  });
  return `<div class="hero-counter" role="group" aria-labelledby="${id}-label">
    <span class="hero-label${hiddenLabel ? ' sr-only' : ''}" id="${id}-label">${label}</span>
    <div class="hero-counter-controls">
      ${step(-1, 'minus', tx(`Diminuer : ${label}`, `Decrease: ${label}`), value <= min)}
      <output id="${id}-value" class="hero-counter-value" aria-live="polite">${text ?? value}</output>
      ${step(1, 'plus', tx(`Augmenter : ${label}`, `Increase: ${label}`), value >= max)}
    </div>
  </div>`;
}

/** Valeur bornée après un clic sur un compteur. */
export const bump = (value, delta, min, max) => Math.min(max, Math.max(min, value + delta));

/**
 * Racine du composant Nodus d'id donné. Certains n'ont pas d'id sur leur racine (Combobox : seul
 * son champ porte `{id}-input` ; Select : son déclencheur porte `{id}-trigger`).
 */
export const componentRoot = id => document.getElementById(id)
  ?? (document.getElementById(`${id}-input`) ?? document.getElementById(`${id}-trigger`))?.closest('[data-component]') ?? null;

/** Événement d'un composant Nodus dont le `detail` ne porte pas d'id : filtré sur sa racine. */
export function onTarget(type, id, fn) {
  document.addEventListener(type, e => {
    const root = componentRoot(id);
    if (root && (e.target === root || root.contains(e.target))) fn(e.detail ?? {}, e);
  });
}

site/hero/kit/parcels.js:
// site/hero/kit/parcels.js — les colis suivis : un état PARTAGÉ entre cartes, un signal Reef nommé
// `hero-parcel`. La carte « Suivi de colis » l'affiche et le modifie ; la Pizzeria y ajoute sa
// livraison au moment de la commande. Deux îlots, un seul état : Reef re-rend la carte Colis sur ce
// signal sans que la Pizzeria sache qu'elle existe.

import { signal } from 'reefjs';

export const MAX_PARCELS = 4;

/** `current` : colis affiché ; `parcels` : { code, step, place, kind?, from?, times? }. */
export const parcels = signal({ current: 'NX-2048', parcels: [{ code: 'NX-2048', step: 2, place: 'home' }] }, 'hero-parcel');

/**
 * Suivre un nouveau colis et l'afficher. Un colis déjà suivi est remplacé ; la liste pleine, le
 * plus ancien laisse sa place (un envoi ne se refuse pas).
 */
export function ship(parcel, s = parcels) {
  const others = s.parcels.filter(p => p.code !== parcel.code);
  s.parcels = [...(others.length >= MAX_PARCELS ? others.slice(1) : others), parcel];
  s.current = parcel.code;
}

site/hero/kit/links.js:
// site/hero/kit/links.js — liens entre cartes. L'hôte qui réunit plusieurs cartes (le carrousel de
// l'accueil) sait en ouvrir une autre et le déclare ici ; une mini-app seule ne le peut pas, et une
// carte n'affiche alors pas le lien (canOpenCard).

let opener = null;

/** Déclaré par l'hôte : `id => …` affiche la carte d'id donné (et y place le focus). */
export const setCardOpener = fn => { opener = fn; };
export const canOpenCard = () => opener !== null;
export const openCard = id => opener?.(id);

site/hero/kit/events.js:
// site/events.js — délégation d'événements, reprise telle quelle du starter (starter/src/events.js) :
// un écouteur par type sur document, jamais d'`on*` inline (Reef les filtre ; GUIDELINES de Nodus
// §2). Les templates restent purs. Le site montre ainsi l'architecture que le starter génère.
//   <button data-action="home:remove" data-id="…">  → on('home:remove', (e, el) => …)
//   <input data-input="home:draft">                 → on('home:draft', fn, 'input')
//   <form data-submit="home:add">                   → on('home:add', fn, 'submit')
//
// Les CustomEvent des composants Nodus (`dialog:close-request`, `dropdown-menu:select`,
// `toggle-group:change-request`…) ne passent pas par un attribut : ils sont émis sur la racine du
// composant et portent toujours `detail.id`. `onComponent()` les route sur cet id — **toujours
// filtrer sur l'id** : sans cela, un Échap sur un dialogue déclenche la fermeture de tous les
// dialogues de l'application, y compris ceux d'un autre écran.
//   onComponent('dialog:close-request', 'dlg-print', detail => { … })

/** type d'événement DOM → nom de l'attribut `data-*` qui porte le nom du gestionnaire. */
const ATTR = {
  click: 'action',
  input: 'input',
  change: 'change',
  submit: 'submit',
  keydown: 'keydown',
  pointerdown: 'pointerdown',
  dblclick: 'dblclick',
  // `focusin` / `focusout`, pas `focus` / `blur` : ces deux-là ne remontent pas, donc aucune
  // délégation n'est possible.
  focusin: 'focusin',
  focusout: 'focusout',
};
// `pointermove`, `pointerout`, `wheel`, `scroll`… ne sont PAS installés par défaut : leur
// écouteur se déclencherait des centaines de fois par seconde dans toute l'application.
// Les ajouter explicitement quand on en a besoin : registerEventType('pointermove').
//
// `wheel`, `touchstart` et `touchmove` : un écouteur posé sur `document` est PASSIF par défaut
// dans les navigateurs, et son `preventDefault()` est ignoré (zoom à la molette, panoramique).
// Le déclarer avec ses options d'écoute (GF-N-01) :
//   registerEventType('wheel', 'wheel', { passive: false })

const handlers = {};
const options = {}; // type → options d'addEventListener (GF-N-01)
const poses = new Map(); // type → listener posé, pour l'enregistrement tardif
let racine = null;

const creerListener = type => e => {
  const el = e.target?.closest?.(`[data-${ATTR[type]}]`);
  const fn = el && handlers[type].get(el.dataset[ATTR[type]]);
  if (fn) fn(e, el);
};

/** Pose l'écouteur d'un type sur la racine, avec les options déclarées pour ce type. */
function poser(type) {
  const listener = creerListener(type);
  racine.addEventListener(type, listener, options[type]);
  poses.set(type, listener);
}

/** Retire l'écouteur d'un type — avec les mêmes options : `capture` fait partie de son identité. */
function retirer(type) {
  racine.removeEventListener(type, poses.get(type), options[type]);
  poses.delete(type);
}

/**
 * Déclare un type d'événement délégable. L'attribut vaut `data-<type>` sauf indication.
 * Utilisable avant comme après `installEvents()`.
 *
 * `opts` est transmis à `addEventListener` (GF-N-01). Deux usages :
 *   - `{ passive: false }` pour `wheel`, `touchstart`, `touchmove` : sur `document`, ces écouteurs
 *     sont passifs par défaut et leur `preventDefault()` est ignoré ;
 *   - `{ capture: true }` pour un événement qui ne remonte pas (`scroll`, `load`, `error`…).
 * Redéclarer un type déjà écouté avec d'autres options remplace son écouteur.
 *
 * @param {string} type        type d'événement DOM ('pointermove', 'wheel'…)
 * @param {string} [attribut]  nom de l'attribut `data-*` (défaut : le type lui-même)
 * @param {AddEventListenerOptions} [opts]  options d'écoute de ce type
 */
export function registerEventType(type, attribut = type, opts) {
  if (!ATTR[type]) ATTR[type] = attribut;
  handlers[type] ??= new Map();
  if (opts && racine && poses.has(type)) retirer(type); // avec les anciennes options
  if (opts) options[type] = opts;
  if (racine && !poses.has(type)) poser(type);
}

for (const type of Object.keys(ATTR)) handlers[type] = new Map();

/** Enregistre un gestionnaire pour la valeur `name` de l'attribut data-* du type d'événement. */
export function on(name, fn, type = 'click') {
  if (!handlers[type]) {
    throw new Error(
      `[app] type d'événement non géré : ${type}. ` +
        `L'ajouter avec registerEventType('${type}') avant de l'utiliser.`,
    );
  }
  handlers[type].set(name, fn);
}

// ── Événements des composants Nodus ─────────────────────────────────────────

/** `nom d'événement` → Map(id du composant → gestionnaire). */
const composants = new Map();

/**
 * Écoute un événement de composant Nodus et le route sur l'`id` du composant émetteur.
 * Un seul écouteur est posé par type d'événement, quel que soit le nombre de composants.
 *
 * Une famille de composants dont l'`id` se calcule (un menu par colonne : `col-0`, `col-1`…) se
 * route par un prédicat sur l'`id`, essayé après les `id` exacts (MJ-N-40) :
 *   onComponent('dropdown-menu:select', id => id.startsWith('col-'), detail => { … detail.id … })
 *
 * @param {string} evenement  ex. 'dialog:close-request', 'toggle-group:change-request'
 * @param {string | ((id: string) => boolean)} id  `id` du composant concerné (`detail.id`), ou prédicat
 * @param {(detail: object, e: CustomEvent) => void} fn
 */
export function onComponent(evenement, id, fn) {
  if (!composants.has(evenement)) {
    composants.set(evenement, new Map());
    document.addEventListener(evenement, e => {
      const fns = composants.get(evenement);
      const cle = e.detail?.id;
      if (cle == null) return;
      const cible = fns.get(cle) ?? [...fns].find(([k]) => typeof k === 'function' && k(cle))?.[1];
      if (cible) cible(e.detail, e);
    });
  }
  composants.get(evenement).set(id, fn);
}

/** Installe les écouteurs (une fois, au démarrage). Retourne une fonction de désinstallation. */
export function installEvents(root = document) {
  racine = root;
  for (const type of Object.keys(ATTR)) {
    if (!poses.has(type)) poser(type);
  }
  return () => {
    for (const type of [...poses.keys()]) retirer(type);
    racine = null;
  };
}

site/hero/kit/card.css:
/* site/hero/kit/card.css — gabarit commun des cartes de la vitrine, partagé par le carrousel de
   l'accueil et par chaque mini-app (site/hero/<carte>/index.html).
   - gabarit : en-tête (icône d'app, nom, actions) · corps · pied ancré en bas (statut, action) ;
   - quatre niveaux de texte : .hero-display (chiffre clé) · .hero-title (objet) · .hero-label
     (libellé, 14/500) · .hero-meta (12, atténué, chiffres tabulaires) ;
   - trois espacements : --space-1-5 (libellé → contrôle), --space-3 (dans un bloc), --space-4
     (entre blocs) ;
   - une teinte d'identité par app (--hero-accent, posée par data-accent) : icône, halo,
     élément signature. Le primaire reste aux actions et aux sélections.
   Des tokens Nodus, plus trois teintes de catégorie propres à la vitrine (rose, ambre, sarcelle) :
   Nodus 4.0.0 a retiré les rôles rose, amber et teal, qui n'en étaient pas. Elles sont déclarées
   ici sur les primitives, avec les trois sélecteurs de thème de _semantic.css. */

@property --hero-accent { syntax: '<color>'; inherits: true; initial-value: transparent; }

:root, [data-theme="light"] { --hero-rose: var(--rose-500); --hero-amber: var(--amber-400); --hero-teal: var(--teal-500); }
@media (prefers-color-scheme: dark) {
  :root:not([data-theme]) { --hero-rose: var(--rose-400); --hero-amber: var(--amber-300); --hero-teal: var(--teal-400); }
}
[data-theme="dark"] { --hero-rose: var(--rose-400); --hero-amber: var(--amber-300); --hero-teal: var(--teal-400); }
:root, [data-theme] {
  --hero-rose-muted:  color-mix(in srgb, var(--hero-rose) 12%, var(--color-bg-elevated));
  --hero-amber-muted: color-mix(in srgb, var(--hero-amber) 12%, var(--color-bg-elevated));
  --hero-teal-muted:  color-mix(in srgb, var(--hero-teal) 12%, var(--color-bg-elevated));
}

[data-accent="rose"]    { --hero-accent: var(--hero-rose);    --hero-accent-muted: var(--hero-rose-muted); }
[data-accent="info"]    { --hero-accent: var(--color-info);    --hero-accent-muted: var(--color-info-muted); }
[data-accent="primary"] { --hero-accent: var(--color-primary); --hero-accent-muted: var(--color-primary-muted); }
[data-accent="warning"] { --hero-accent: var(--color-warning); --hero-accent-muted: var(--color-warning-muted); }
[data-accent="amber"]   { --hero-accent: var(--hero-amber);   --hero-accent-muted: var(--hero-amber-muted); }
[data-accent="teal"]    { --hero-accent: var(--hero-teal);    --hero-accent-muted: var(--hero-teal-muted); }
[data-accent="success"] { --hero-accent: var(--color-success); --hero-accent-muted: var(--color-success-muted); }

/* ── Mini-app : la carte seule, centrée dans sa page ── */
.hero-app {
  min-height: 100dvh; box-sizing: border-box; display: grid; place-items: center;
  padding: var(--space-4) var(--space-3); background: var(--color-bg-state); color: var(--color-fg);
}
/* La hauteur du gabarit (en-tête 64 + corps 320 + pied 64) : dans le carrousel, les diapositives
   étirées la donnent ; seule, la carte la reçoit ici — les listes qui « prennent la hauteur
   restante » (discussion, menu, Memory) en ont besoin. */
.hero-app > .hero-card { max-width: 28rem; min-height: calc(2 * var(--space-16) + 20rem); }

/* ── Gabarit de carte ── */
.hero-card { width: 100%; display: flex; flex-direction: column; padding: 0; border-radius: var(--radius-xl); box-shadow: var(--shadow-lg); }
.hero-island { flex: 1; display: flex; flex-direction: column; min-width: 0; }
.hero-island p { margin: 0; }
.hero-card-head {
  /* L'en-tête dit quelle app c'est, rien d'autre : ses contrôles et son état sont dans le corps. */
  display: grid; grid-template-columns: auto minmax(0, 1fr); align-items: center; gap: var(--space-3);
  min-height: var(--space-16); padding: var(--space-2) var(--space-4); border-bottom: 1px solid var(--color-border);
}
.hero-app-icon {
  width: var(--space-8); height: var(--space-8); display: grid; place-items: center;
  border-radius: var(--radius-md); background: var(--hero-accent-muted, var(--color-primary-muted)); color: var(--hero-accent, var(--color-primary));
}
.hero-app-id { min-width: 0; }
.hero-app-name { margin: 0; font-size: var(--text-sm); line-height: var(--leading-5); font-weight: var(--font-semibold); }
/* Lien vers le code (carrousel de l'accueil) : une pastille, pour qu'il se lise comme un lien
   cliquable et non comme une mention ; centrée sur la ligne « Exemple fictif · 01/12 ». */
.hero-app-id .hero-meta { display: flex; align-items: center; gap: var(--space-1); }
.hero-code-link {
  display: inline-flex; align-items: center; gap: var(--space-1); flex: none;
  height: var(--space-5); padding: 0 var(--space-1-5); border: 1px solid var(--color-border-control); border-radius: var(--radius-full);
  color: var(--color-fg); font-weight: var(--font-medium); line-height: 1; text-decoration: none;
  transition: background var(--duration-fast) var(--ease-default), border-color var(--duration-fast) var(--ease-default);
}
.hero-code-link:hover { background: var(--color-bg-muted); border-color: var(--color-fg-muted); }
.hero-code-link:focus-visible { outline: 2px solid var(--color-ring); outline-offset: 2px; }
.hero-app-id > * { white-space: nowrap; overflow: hidden; text-overflow: ellipsis; } /* en-tête étroit : une ligne, jamais deux */
/* Compteur − valeur + */
.hero-counter { display: flex; flex-direction: column; gap: var(--space-1-5); }
.hero-counter-controls { display: flex; align-items: center; gap: var(--space-1); }
.hero-counter-value { min-width: 5.5rem; text-align: center; font-size: var(--text-sm); font-variant-numeric: tabular-nums; }
.hero-card-foot .hero-counter-value { min-width: var(--space-8); }
.hero-counter [aria-disabled="true"] { opacity: .45; cursor: not-allowed; } /* même atténuation que les boutons inactifs de Nodus */
.hero-card-body { flex: 1; display: flex; flex-direction: column; gap: var(--space-4); padding: var(--space-4); min-width: 0; }
.hero-card-foot {
  display: flex; align-items: center; justify-content: space-between; gap: var(--space-3);
  min-height: var(--space-16); padding: var(--space-2) var(--space-4);
  border-top: 1px solid var(--color-border); background: var(--color-bg-muted);
  border-radius: 0 0 var(--radius-xl) var(--radius-xl);
}
/* ── Texte ── */
.hero-display { font-size: var(--text-3xl); line-height: var(--leading-9); font-weight: var(--font-semibold); letter-spacing: var(--tracking-tight); font-variant-numeric: tabular-nums; }
.hero-display--sm { font-size: var(--text-2xl); line-height: var(--leading-8); }
.hero-title { font-size: var(--text-base); line-height: var(--leading-6); font-weight: var(--font-semibold); }
.hero-label { font-size: var(--text-sm); line-height: var(--leading-5); font-weight: var(--font-medium); }
.hero-meta { font-size: var(--text-xs); line-height: var(--leading-4); color: var(--color-fg-muted); font-variant-numeric: tabular-nums; }
.hero-mono { font-family: var(--font-mono); }
/* ── Mise en page ── */
.hero-stack { display: flex; flex-direction: column; gap: var(--space-4); min-width: 0; }
.hero-field { display: flex; flex-direction: column; gap: var(--space-1-5); min-width: 0; }
.hero-split > .tabs-list { justify-self: start; } /* une liste d'onglets garde sa largeur, son fond ne s'étire pas */
.hero-split { display: grid; grid-template-columns: minmax(0, 1fr) auto; align-items: center; gap: var(--space-3); }
.hero-actions { display: flex; align-items: center; gap: var(--space-2); }
.hero-legend { display: flex; align-items: center; gap: var(--space-1); }
.hero-popover-form { display: flex; flex-direction: column; gap: var(--space-2); width: var(--hover-card-width); }
.hero-composer { display: flex; align-items: center; gap: var(--space-2); flex: 1; min-width: 0; }
.hero-composer .input-group { flex: 1; min-width: 0; }
/* Focus visible sur les éléments propres à la vitrine */
:is(.hero-queue-item, .hero-reaction, .hero-emoji, .hero-link-btn, .hero-icon-btn, .hero-chat-log, .hero-subtasks):focus-visible {
  outline: 2px solid var(--color-ring); outline-offset: 2px;
}
/* Bascules d'icône : l'état se lit à la couleur et au remplissage de l'icône, pas au fond inversé de Toggle. */
:is(.hero-like, .hero-mode, .hero-star) { --toggle-on-bg: transparent; }
.hero-foot-figure { font-size: var(--text-base); line-height: var(--leading-6); font-weight: var(--font-semibold); color: var(--color-fg); }
.hero-setting { display: grid; grid-template-columns: minmax(0, 1fr) auto; align-items: center; gap: var(--space-3); padding-block: var(--space-2); border-top: 1px solid var(--color-border); }
.hero-setting-text { display: flex; flex-direction: column; gap: var(--space-0-5); min-width: 0; }
/* Notifications : groupe de bascules sur toute la largeur. */
.hero-fill-group { display: flex; width: 100%; }
.hero-fill-group .toggle-group-item { flex: 1; justify-content: center; }
.hero-timeline { --timeline-dot-size: var(--space-5); --timeline-gap: var(--space-1); font-size: var(--text-sm); }
.hero-timeline .timeline-title { font-weight: var(--font-normal); }
.hero-timeline .is-current .timeline-title { font-weight: var(--font-semibold); }
.hero-timeline .is-future { color: var(--color-fg-muted); }
.hero-timeline .is-current .timeline-dot { animation: hero-pulse 2s var(--ease-out) infinite; }
@keyframes hero-pulse { from { box-shadow: 0 0 0 0 color-mix(in srgb, var(--_pulse, var(--color-primary)) 45%, transparent); } to { box-shadow: 0 0 0 var(--space-2) transparent; } }
.hero-tracking { display: flex; align-items: center; gap: var(--space-1); }
.hero-progress-thin { --progress-height: var(--space-1); }
.hero-price-block { display: flex; flex-direction: column; }

/* Mouvement réduit */
@media (prefers-reduced-motion: reduce) {
  .hero-timeline .is-current .timeline-dot { animation: none; }
}

/* Téléphone */
@media (max-width: 30rem) {
  .hero-pair { align-items: start; }
  .hero-pair .hero-counter-value { min-width: 0; flex: 1; }
  .hero-pair .hero-counter-controls { min-width: 0; }
}
